import hashlib, json, pathlib, sys

def fail(msg):
    print('FAIL:',msg); return 1

def main(argv):
    if not argv: return fail('receipt path required')
    rp=pathlib.Path(argv[0]); root=pathlib.Path(argv[1]) if len(argv)>1 else pathlib.Path('.')
    d=json.loads(rp.read_text(encoding='utf-8'))
    p=root/d['artifact']; b=p.read_bytes(); n=d['pinned_prefix_bytes']
    if len(b)<n: return fail('artifact shorter than pinned prefix')
    if hashlib.sha256(b[:n]).hexdigest()!=d['pinned_prefix_sha256']:
        return fail('pinned prefix hash mismatch')
    at=0
